import numpy as np

def linear_const(a, q, y0, t):
    """y(t) for y' = a y + q, y(0) = y0. t may be an array; a may be 0."""
    t = np.asarray(t, dtype=float)
    if a == 0:
        return y0 + q * t
    return (y0 + q / a) * np.exp(a * t) - q / a

def payoff_time(L0, r, payment):
    """Years until L' = r L - payment, L(0) = L0, reaches 0."""
    if payment <= r * L0:
        raise ValueError("the payment never covers the interest")
    return float(np.log(payment / (payment - r * L0)) / r)
